// z2ui5cc.cc.CodeEditor - makes sap.ui.codeeditor.CodeEditor usable from an                                                                                                                                                                                   
// abap2UI5 view.                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                             
// This control adds no editor of its own. UI5 already ships one - an ACE                                                                                                                                                                                      
// editor with syntax highlighting for some eighty languages, markdown among                                                                                                                                                                                   
// them, loaded from the UI5 distribution rather than from a CDN, so it works                                                                                                                                                                                  
// in a system without internet. There is no reason to wrap a third-party                                                                                                                                                                                      
// editor next to it.                                                                                                                                                                                                                                          
//                                                                                                                                                                                                                                                             
// What it does add is a way to REACH it. sap.ui.codeeditor is not in the                                                                                                                                                                                      
// abap2UI5 manifest's dependencies, and on 1.71 Fragment/XMLView still process                                                                                                                                                                                
// their XML with the synchronous strategy: an unloaded CodeEditor written                                                                                                                                                                                     
// straight into a view is fetched by synchronous XHR and executed with eval,                                                                                                                                                                                  
// which a Content-Security-Policy without 'unsafe-eval' blocks. The same                                                                                                                                                                                      
// reason the framework's own developer tools preload the modules by hand                                                                                                                                                                                      
// before opening their fragment.                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                             
// So the app writes <z2ui5cc:CodeEditor/>, never <codeeditor:CodeEditor/>.                                                                                                                                                                                    
// The class name the XML parser has to resolve is this module; the editor                                                                                                                                                                                     
// itself is required asynchronously here and only then created, which is a                                                                                                                                                                                    
// normal AMD load - no synchronous XHR, no eval.                                                                                                                                                                                                              
sap.ui.define(["sap/ui/core/Control", "z2ui5cc/cc/Util"], (Control, Util) => {                                                                                                                                                                                 
  "use strict";                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                               
  // sap/ui/codeeditor/library comes along so the library's theme resources                                                                                                                                                                                    
  // are loaded - requiring only the control leaves it unstyled.                                                                                                                                                                                               
  const MODULES = ["sap/ui/codeeditor/library", "sap/ui/codeeditor/CodeEditor"];                                                                                                                                                                               
                                                                                                                                                                                                                                                               
  // one shared promise: ten editors on a page load ACE once                                                                                                                                                                                                   
  let pending = null;                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
  function loadEditor() {                                                                                                                                                                                                                                      
    if (pending) return pending;                                                                                                                                                                                                                               
    pending = new Promise((resolve, reject) => {                                                                                                                                                                                                               
      sap.ui.require(                                                                                                                                                                                                                                          
        MODULES,                                                                                                                                                                                                                                               
        (lib, CodeEditor) => resolve(CodeEditor),                                                                                                                                                                                                              
        (e) => reject(e || new Error("sap.ui.codeeditor is not available")),                                                                                                                                                                                   
      );                                                                                                                                                                                                                                                       
    });                                                                                                                                                                                                                                                        
    // a failed load must not be cached as failed forever                                                                                                                                                                                                      
    pending.catch(() => {                                                                                                                                                                                                                                      
      pending = null;                                                                                                                                                                                                                                          
    });                                                                                                                                                                                                                                                        
    return pending;                                                                                                                                                                                                                                            
  }                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
  return Control.extend("z2ui5cc.cc.CodeEditor", {                                                                                                                                                                                                             
    metadata: {                                                                                                                                                                                                                                                
      properties: {                                                                                                                                                                                                                                            
        // the text - bind it two-way to the ABAP attribute that carries it                                                                                                                                                                                    
        value: { type: "string", defaultValue: "" },                                                                                                                                                                                                           
        // any type sap.ui.codeeditor supports: markdown, abap, javascript,                                                                                                                                                                                    
        // json, xml, html, css, sql, yaml ... the ACE mode for it is loaded                                                                                                                                                                                   
        // from the UI5 distribution when it is first used                                                                                                                                                                                                     
        type: { type: "string", defaultValue: "markdown" },                                                                                                                                                                                                    
        width: { type: "string", defaultValue: "100%" },                                                                                                                                                                                                       
        // ACE needs a resolvable height - a percentage only works when the                                                                                                                                                                                    
        // parent has one, so an explicit value is usually the safer choice                                                                                                                                                                                    
        height: { type: "string", defaultValue: "20rem" },                                                                                                                                                                                                     
        editable: { type: "boolean", defaultValue: true },                                                                                                                                                                                                     
        lineNumbers: { type: "boolean", defaultValue: true },                                                                                                                                                                                                  
        // `default`, `dark`, `hcb`, ... empty leaves the UI5 theme's choice                                                                                                                                                                                   
        colorTheme: { type: "string", defaultValue: "" },                                                                                                                                                                                                      
      },                                                                                                                                                                                                                                                       
      aggregations: {                                                                                                                                                                                                                                          
        // the real editor, created here rather than written in the view                                                                                                                                                                                       
        _editor: { type: "sap.ui.core.Control", multiple: false, visibility: "hidden" },                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
      events: {                                                                                                                                                                                                                                                
        // fired on every keystroke, with the current text                                                                                                                                                                                                     
        liveChange: { parameters: { value: { type: "string" } } },                                                                                                                                                                                             
      },                                                                                                                                                                                                                                                       
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    init() {                                                                                                                                                                                                                                                   
      this._failed = false;                                                                                                                                                                                                                                    
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _editorControl() {                                                                                                                                                                                                                                         
      return this.getAggregation("_editor");                                                                                                                                                                                                                   
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // The text ACE really shows.                                                                                                                                                                                                                              
    //                                                                                                                                                                                                                                                         
    // NOT editor.getValue(): sap.ui.codeeditor writes its own `value` property                                                                                                                                                                                
    // from the editor on BLUR only, so while the user is typing the property                                                                                                                                                                                  
    // still carries the text from before. Comparing against it - or letting it                                                                                                                                                                                
    // reach the model - is what makes an editor look like it ignores the                                                                                                                                                                                      
    // backend.                                                                                                                                                                                                                                                
    _text(editor) {                                                                                                                                                                                                                                            
      return editor.getCurrentValue                                                                                                                                                                                                                            
        ? editor.getCurrentValue()                                                                                                                                                                                                                             
        : editor.getValue();                                                                                                                                                                                                                                   
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // Pushes the properties onto the editor. Called after every render, so a                                                                                                                                                                                  
    // changed property arrives without this control needing a setter per                                                                                                                                                                                      
    // property - a property change invalidates, and invalidation renders.                                                                                                                                                                                     
    _apply() {                                                                                                                                                                                                                                                 
      const editor = this._editorControl();                                                                                                                                                                                                                    
      if (!editor) return;                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
      if (editor.getType() !== this.getType()) editor.setType(this.getType());                                                                                                                                                                                 
      editor.setEditable(this.getEditable());                                                                                                                                                                                                                  
      editor.setLineNumbers(this.getLineNumbers());                                                                                                                                                                                                            
      if (this.getColorTheme()) editor.setColorTheme(this.getColorTheme());                                                                                                                                                                                    
      editor.setWidth("100%");                                                                                                                                                                                                                                 
      editor.setHeight("100%");                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                               
      // Only when it really differs: setValue resets the cursor to the start,                                                                                                                                                                                 
      // which would fight the user on every keystroke once the value is bound                                                                                                                                                                                 
      // two-way and comes back through the model. Compared against what ACE                                                                                                                                                                                   
      // shows, not against the editor's property - see _text( ).                                                                                                                                                                                              
      if (this._text(editor) !== (this.getValue() || "")) {                                                                                                                                                                                                    
        editor.setValue(this.getValue() || "");                                                                                                                                                                                                                
      }                                                                                                                                                                                                                                                        
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    // A new value from the model.                                                                                                                                                                                                                             
    //                                                                                                                                                                                                                                                         
    // It is pushed into the editor here instead of on the next rendering, and                                                                                                                                                                                 
    // the invalidation is suppressed on purpose. sap.ui.codeeditor restores                                                                                                                                                                                   
    // ACE from its own `value` property in every onAfterRendering, and that                                                                                                                                                                                   
    // property is only refreshed on blur - so a re-render triggered by this                                                                                                                                                                                   
    // setter would first restore the OLD text, fire liveChange for it, and                                                                                                                                                                                    
    // that echo would travel back into the model and undo the change on its                                                                                                                                                                                   
    // way. Writing the editor directly keeps the property, ACE and the model                                                                                                                                                                                  
    // on the same text.                                                                                                                                                                                                                                       
    setValue(value) {                                                                                                                                                                                                                                          
      const next = value === undefined || value === null ? "" : String(value);                                                                                                                                                                                 
      this.setProperty("value", next, true);                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                               
      const editor = this._editorControl();                                                                                                                                                                                                                    
      // No editor yet - the value is in the property, and _apply( ) puts it                                                                                                                                                                                   
      // into the editor as soon as the module has arrived.                                                                                                                                                                                                    
      if (editor && this._text(editor) !== next) editor.setValue(next);                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
      return this;                                                                                                                                                                                                                                             
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    _create(CodeEditor) {                                                                                                                                                                                                                                      
      const editor = new CodeEditor(`${this.getId()}-editor`, {                                                                                                                                                                                                
        type: this.getType(),                                                                                                                                                                                                                                  
        value: this.getValue() || "",                                                                                                                                                                                                                          
        editable: this.getEditable(),                                                                                                                                                                                                                          
        lineNumbers: this.getLineNumbers(),                                                                                                                                                                                                                    
        width: "100%",                                                                                                                                                                                                                                         
        height: "100%",                                                                                                                                                                                                                                        
      });                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
      // The model has to follow the typing, not the blur: sample apps bind the                                                                                                                                                                                
      // same attribute to this editor and to a preview and expect the preview                                                                                                                                                                                 
      // to keep up. suppressInvalidate is on - the value came FROM the editor,                                                                                                                                                                                
      // so writing it back into the editor is what must not happen.                                                                                                                                                                                           
      editor.attachLiveChange((event) => {                                                                                                                                                                                                                     
        const value = event.getParameter("value") ?? this._text(editor);                                                                                                                                                                                       
        // Repairs sap.ui.codeeditor's own bookkeeping: it only writes this                                                                                                                                                                                    
        // property on blur, yet restores ACE from it on every render. Left                                                                                                                                                                                    
        // alone, any re-render during typing throws the typing away.                                                                                                                                                                                          
        editor.setProperty("value", value, true);                                                                                                                                                                                                              
        this.setProperty("value", value, true);                                                                                                                                                                                                                
        this.fireLiveChange({ value });                                                                                                                                                                                                                        
      });                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
      this.setAggregation("_editor", editor);                                                                                                                                                                                                                  
      // the renderer only draws the editor once the aggregation is filled, so                                                                                                                                                                                 
      // ask for the second render that actually places it                                                                                                                                                                                                     
      this.invalidate();                                                                                                                                                                                                                                       
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    onAfterRendering() {                                                                                                                                                                                                                                       
      if (this._editorControl()) {                                                                                                                                                                                                                             
        this._apply();                                                                                                                                                                                                                                         
        return;                                                                                                                                                                                                                                                
      }                                                                                                                                                                                                                                                        
      if (this._failed) return;                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                               
      loadEditor()                                                                                                                                                                                                                                             
        .then((CodeEditor) => {                                                                                                                                                                                                                                
          if (Util.isDestroyed(this)) return;                                                                                                                                                                                                                  
          this._create(CodeEditor);                                                                                                                                                                                                                            
        })                                                                                                                                                                                                                                                     
        .catch((e) => {                                                                                                                                                                                                                                        
          this._failed = true;                                                                                                                                                                                                                                 
          Util.logError("CodeEditor: sap.ui.codeeditor could not be loaded", e);                                                                                                                                                                               
          const host = document.getElementById(`${this.getId()}-host`);                                                                                                                                                                                        
          if (host) {                                                                                                                                                                                                                                          
            host.textContent =                                                                                                                                                                                                                                 
              "sap.ui.codeeditor is not available in this UI5 distribution.";                                                                                                                                                                                  
            host.style.color = "var(--sapNegativeTextColor, #b00)";                                                                                                                                                                                            
          }                                                                                                                                                                                                                                                    
        });                                                                                                                                                                                                                                                    
    },                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
    renderer: {                                                                                                                                                                                                                                                
      apiVersion: 2,                                                                                                                                                                                                                                           
      render(rm, control) {                                                                                                                                                                                                                                    
        rm.openStart("div", control);                                                                                                                                                                                                                          
        const width = Util.toCssSize(control.getWidth());                                                                                                                                                                                                      
        const height = Util.toCssSize(control.getHeight());                                                                                                                                                                                                    
        if (width) rm.style("width", width);                                                                                                                                                                                                                   
        if (height) rm.style("height", height);                                                                                                                                                                                                                
        rm.openEnd();                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
        const editor = control.getAggregation("_editor");                                                                                                                                                                                                      
        if (editor) {                                                                                                                                                                                                                                          
          rm.renderControl(editor);                                                                                                                                                                                                                            
        } else {                                                                                                                                                                                                                                               
          // placeholder until the module is there - also where a load failure                                                                                                                                                                                 
          // puts its message                                                                                                                                                                                                                                  
          rm.openStart("div", `${control.getId()}-host`);                                                                                                                                                                                                      
          rm.openEnd();                                                                                                                                                                                                                                        
          rm.close("div");                                                                                                                                                                                                                                     
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        rm.close("div");                                                                                                                                                                                                                                       
      },                                                                                                                                                                                                                                                       
    },                                                                                                                                                                                                                                                         
  });                                                                                                                                                                                                                                                          
});                                                                                                                                                                                                                                                            